"""Примеры matplotlib в окне tkinter.

mpldemo            окно с выбором примера
mpldemo bars       сразу открыть пример
python3 -m mpldemo.bars   пример отдельно, через pyplot

Каждый пример - модуль с функцией draw(fig), которая рисует на готовой фигуре.
"""

EXAMPLES = [
    ("lines", "Линии"),
    ("bars", "Столбцы"),
    ("hist", "Гистограмма"),
    ("scatter", "Точки"),
    ("pie", "Круговая"),
    ("contour", "Контуры"),
    ("image", "Картинка"),
    ("subplots", "Четыре графика"),
    ("surface", "Поверхность 3D"),
    ("animation", "Анимация"),
]


def run(draw):
    import matplotlib.pyplot as plt
    keep = draw(plt.figure())
    plt.show()
    return keep
